import json, os, sys, time, platform, shutil, resource

report = {}
def save():
    with open("world_limits_report.json", "w") as f:
        json.dump(report, f, indent=2, default=str)

t_start = time.time()

report["python"] = sys.version
report["platform"] = platform.platform()
report["machine"] = platform.machine()
report["cpu_count"] = os.cpu_count()
try:
    report["loadavg"] = os.getloadavg()
except Exception as e:
    report["loadavg"] = str(e)
save()

avail = {}
for mod in ["numpy", "scipy", "pandas", "matplotlib", "requests", "PIL",
            "cryptography", "sqlite3", "zlib", "ctypes", "multiprocessing",
            "threading", "subprocess", "socket", "ssl", "decimal", "fractions",
            "mmap", "pickle", "gzip", "bz2", "lzma", "pytest", "flask",
            "django", "torch", "sklearn", "sympy"]:
    try:
        m = __import__(mod)
        avail[mod] = getattr(m, "__version__", "builtin/unknown")
    except Exception:
        avail[mod] = "MISSING"
report["libraries"] = avail
save()

report["recursion_limit"] = sys.getrecursionlimit()
report["int_max_str_digits"] = getattr(sys, "get_int_max_str_digits", lambda: "n/a")()
rl = {}
for name in ["AS", "DATA", "CPU", "NOFILE", "STACK", "NPROC", "FSIZE", "CORE"]:
    try:
        lim = resource.getrlimit(getattr(resource, "RLIMIT_" + name))
        rl[name] = [lim[0], lim[1]]
    except Exception as e:
        rl[name] = str(e)
report["rlimits_soft_hard"] = rl
save()

# kernel / cgroup memory info (no allocation)
info = {}
try:
    with open("/proc/meminfo") as f:
        for line in f:
            k, v = line.split(":", 1)
            info[k] = v.strip()
except Exception as e:
    info["error"] = str(e)
report["meminfo"] = info
for p in ["/sys/fs/cgroup/memory.max", "/sys/fs/cgroup/memory/memory.limit_in_bytes",
          "/sys/fs/cgroup/cpu.max", "/sys/fs/cgroup/pids.max",
          "/sys/fs/cgroup/memory.swap.max"]:
    try:
        with open(p) as f:
            report["cgroup:" + p] = f.read().strip()
    except Exception as e:
        report["cgroup:" + p] = "unavailable: " + str(e)
save()

# CPU speed: pure python spin
def spin(n):
    s = 0
    for i in range(n):
        s += i * i
    return s
t0 = time.time(); spin(2_000_000); dt = time.time() - t0
report["cpu_pure_python"] = {"iters": 2_000_000, "seconds": round(dt, 4),
                             "Miters_per_s": round(2e6 / dt / 1e6, 2)}
t0 = time.time(); x = 0
while time.time() - t0 < 1.0:
    x += 1
report["cpu_busy_loop_1s"] = {"iterations": x}
save()

try:
    import numpy as np
    a = np.ones(5_000_000, dtype=np.float64)
    t0 = time.time()
    for _ in range(20):
        a = a * 1.0000001 + 0.5
    report["cpu_numpy"] = {"vector_len": 5_000_000, "loops": 20,
                           "seconds": round(time.time() - t0, 4)}
    del a
except Exception as e:
    report["cpu_numpy"] = repr(e)
save()

du = shutil.disk_usage(os.getcwd())
report["disk_GB"] = {"total": round(du.total / 1e9, 2), "free": round(du.free / 1e9, 2),
                     "used": round(du.used / 1e9, 2)}
blob = b"x" * (32 * 1024 * 1024)
t0 = time.time()
with open("probe_blob.bin", "wb") as f:
    f.write(blob)
wt = time.time() - t0
t0 = time.time()
with open("probe_blob.bin", "rb") as f:
    f.read()
report["io_32MB"] = {"write_s": round(wt, 4), "read_s": round(time.time() - t0, 4)}
os.remove("probe_blob.bin")
save()

t0 = time.time()
try:
    import subprocess
    out = subprocess.run([sys.executable, "-c", "print('child-ok')"],
                         capture_output=True, text=True, timeout=30)
    report["subprocess"] = {"ok": out.stdout.strip() == "child-ok",
                            "seconds": round(time.time() - t0, 3)}
except Exception as e:
    report["subprocess"] = repr(e)

report["probe1_runtime_s"] = round(time.time() - t_start, 2)
save()
print(json.dumps(report, indent=2, default=str))
